import fs from "node:fs";
import assert from "node:assert/strict";
const api=fs.readFileSync("shared/neon-builder-api.js","utf8");
const storefront=fs.readFileSync("shared/storefront.js","utf8");
const css=fs.readFileSync("shared/storefront.css","utf8");
const adminApi=fs.readFileSync("admin/neon-builder-api.js","utf8");
const bundle=JSON.parse(fs.readFileSync(".github/backups/studio-production-bundle.json","utf8"));
assert.ok(api.includes("async function authContext("),"Neon Auth context must be defined");
assert.ok(api.includes("async function getPublishPreflight("),"Publish preflight must exist");
assert.ok(api.includes("submit_storefront_quote_request"),"Public quote RPC must be wired");
assert.ok(api.includes("inventory_verified"),"Publish preflight must require verified inventory");
assert.ok(storefront.includes("function quickOrderSheet(limit=150)"),"Wholesale quick order sheet must exist");
assert.ok(storefront.includes("async function submitQuote("),"Wholesale quote form must persist");
assert.ok(storefront.includes("function reorderTrackedOrder("),"Order reorder must exist");
assert.ok(storefront.includes("data-reorder-tracked"),"Reorder control must be rendered");
assert.ok(storefront.includes("deliveryZoneForArea"),"Checkout must use configured delivery zones");
assert.ok(storefront.includes("case\"about\":case\"contact\":case\"faq\":case\"delivery\":return contentPage(key);case\"returns\":return returnsPage();"),"About/contact/FAQ/delivery must route to their own content pages");
assert.ok(storefront.includes("function quantityStep(p)"),"Fresh produce must support variable-weight quantity steps");
assert.ok(storefront.includes("function canOrderProduct(p)")&&storefront.includes("inventory_verified"),"Unverified or demo inventory must be visibly non-orderable in the customer experience");
assert.ok(storefront.includes('location.pathname.endsWith("/storefront.html")'),"Central Studio preview product and checkout links must stay on storefront.html, not route to the dashboard.");
assert.ok(storefront.includes("function searchSuggestions(query)")&&storefront.includes("sf-search-suggestions"),"Header search must provide live product suggestions");
assert.ok(storefront.includes("function mobileDock()")&&storefront.includes("sf-mobile-dock"),"All storefronts must provide mobile-first quick navigation");
assert.ok(storefront.includes("Catalogue preview")&&storefront.includes("noindex,nofollow"),"Unverified catalogues and unpublished storefronts must be clearly marked and noindexed");
assert.ok(storefront.includes("sfSubstitution"),"Fresh produce checkout must capture substitution preferences");
assert.ok(storefront.includes("const storefrontApi=()=>window.HFNeonBuilderApi||window.WPNeonBuilderApi;"),"The shared renderer must support both public and private-preview API clients");
assert.ok(storefront.includes("quickOrderSheet(12)"),"Wholesale home must expose a short quick-order sheet");
assert.ok(css.includes("sf-bulk-qty"),"Wholesale quick order must be styled");
assert.ok(css.includes("sf-supermarket-promos")&&css.includes("sf-farm-story")&&css.includes("sf-express-promise")&&css.includes("sf-b2b-benefits"),"All four template experiences need their own visual modules");
assert.ok(adminApi.includes("async function submitQuoteRequest(")&&adminApi.includes("submitQuoteRequest,"),"Private preview API must expose wholesale quote submission");
assert.ok(adminApi.includes("async function updateCentralQuote(")&&adminApi.includes("quoteRequests:quoteRequests||[]")&&adminApi.includes("rpc/respond_to_storefront_quote_request"),"Central commerce must load and update wholesale quote requests through the owner-safe RPC");
const commerce=fs.readFileSync("admin/commerce.js","utf8");
const refundMigration=fs.readFileSync("migrations/20261107_return_refund_management.sql","utf8");
assert.ok(adminApi.includes("async function centralProcessReturnRefund(")&&adminApi.includes("rpc/central_process_return_refund")&&adminApi.includes("centralProcessReturnRefund,"),"Central Commerce must expose the owner-authorized refund RPC.");
assert.ok(commerce.includes("data-return-refund")&&commerce.includes("return-received")&&commerce.includes("refundableForOrder"),"Returns UI must require receipt inspection and show the capped refund form.");
assert.ok(refundMigration.includes("CREATE OR REPLACE FUNCTION builder.central_process_return_refund")&&refundMigration.includes("transaction_type='refund'")&&refundMigration.includes("'Customer refund'"),"Refund RPC must atomically record a payment refund and finance expense.");
assert.ok(refundMigration.includes("REVOKE ALL ON FUNCTION builder.central_process_return_refund")&&refundMigration.includes("GRANT EXECUTE ON FUNCTION builder.central_process_return_refund(uuid,numeric,text,text,text) TO authenticated"),"Refund RPC must be owner-authenticated only.");
assert.ok(refundMigration.includes("'partially_paid'"),"Partial collections must not be reported as unpaid.");
const quoteMigration=fs.readFileSync("migrations/20261107_quote_response_rpc.sql","utf8");
assert.ok(quoteMigration.includes("SECURITY DEFINER")&&quoteMigration.includes("auth.uid()")&&quoteMigration.includes("q.owner_id = v_user_id")&&quoteMigration.includes("TO authenticated")&&quoteMigration.includes("FROM anonymous"),"Quote response RPC must enforce authenticated owner-only access");
const commerceBundle=JSON.parse(fs.readFileSync(".github/backups/studio-production-bundle.json","utf8"));
assert.ok(commerceBundle["admin/commerce.js"].includes("function quotesPage()")&&commerceBundle["admin/commerce.js"].includes("data-quote-update"),"Quote management UI must be deployed with the Studio bundle");
assert.ok(commerceBundle["admin/commerce.html"].includes('data-tab="quotes"'),"Quote management must be reachable from Central Commerce navigation");
assert.ok(commerceBundle["admin/commerce.js"].includes("data-return-refund")&&commerceBundle["admin/commerce.js"].includes("return-received"),"Refund controls must be present in the production Studio bundle.");
assert.ok(commerceBundle["admin/neon-builder-api.js"].includes("centralProcessReturnRefund"),"Refund API must be present in the production Studio bundle.");
assert.ok(commerceBundle["admin/commerce.html"].includes("20261107-refund-management-v1"),"Production Studio bundle must use the refund workflow cache version.");
assert.equal(commerceBundle["admin/commerce.js"],commerce,"Production Studio commerce UI must match the tested source.");
assert.equal(commerceBundle["admin/neon-builder-api.js"],adminApi,"Production Studio API must match the tested source.");
assert.equal(commerceBundle["admin/commerce.css"],fs.readFileSync("admin/commerce.css","utf8"),"Production Studio CSS must match the tested source.");
assert.equal(commerceBundle["admin/commerce.html"],fs.readFileSync("admin/commerce.html","utf8"),"Production Studio HTML must match the tested source.");
assert.equal(bundle["storefront.js"],storefront,"ShipStatic preview storefront JS must match the tested shared runtime");
assert.equal(bundle["storefront.css"],css,"ShipStatic preview CSS must match the tested shared styles");
assert.equal(bundle["admin/neon-builder-api.js"],adminApi,"ShipStatic preview API must match the tested Neon API");
const templateScript=bundle["admin/wordpress-templates.js"];
assert.ok(templateScript.includes("async function updateBrowserPreviewLinks(templateKey)") && templateScript.includes('const href="../storefront.html?site="+encodeURIComponent(website.slug)+"&preview=1"') && templateScript.includes('links.forEach(link=>{link.href=href;link.dataset.previewReady="true";})'),"Preview buttons must resolve the signed-in merchant storefront slug before opening preview.");
assert.ok(bundle["storefront.html"].includes("storefront.js?v=20261108-preview-route-v1"),"Preview HTML must bust stale storefront JS cache");
assert.ok(bundle["admin/wordpress-templates.html"].includes("wordpress-templates.js?v=20261108-preview-route-v1"),"Template library must bust stale preview-link JS cache");
for(const site of ["general-supermarket","fresh-produce","express-grocery","wholesale-bulk"]){
 const html=fs.readFileSync(site+"/index.html","utf8");
 assert.ok(html.includes("@neon/neon-js"),site+" must use the independent Neon client");
 assert.ok(!html.toLowerCase().includes("supabase"),site+" must not use Supabase");
 assert.ok(html.includes("20261108-preview-route-v1"),site+" must use the current customer storefront asset cache version");
}
assert.ok(!api.toLowerCase().includes("supabase"),"Shared API must remain independent of Supabase");
assert.ok(!storefront.toLowerCase().includes("supabase"),"Shared storefront must remain independent of Supabase");
assert.ok(!adminApi.includes("halalfoodbd.official@gmail.com"),"Admin API must not hard-code a single merchant email");
assert.ok(adminApi.includes("template_key=eq.")&&adminApi.includes("store-"),"Each merchant must receive a unique store slug while reusing owned template sites");
assert.ok(api.includes("place_storefront_order_idempotent")&&adminApi.includes("place_storefront_order_idempotent"),"Both storefront API clients must use the server-side idempotent checkout RPC");
assert.ok(storefront.includes("checkoutIdempotencyKey")&&storefront.includes("sessionStorage.setItem"),"Checkout retry keys must persist across client retries");
const tenantMigration=fs.readFileSync("migrations/20261107_multi_tenant_owner_scope.sql","utf8");
const idempotencyMigration=fs.readFileSync("migrations/20261107_checkout_idempotency.sql","utf8");
assert.ok(tenantMigration.includes("AS RESTRICTIVE")&&tenantMigration.includes("auth.uid()"),"Tenant scope migration must constrain authenticated access to the signed-in owner");
assert.ok(idempotencyMigration.includes("place_storefront_order_idempotent")&&idempotencyMigration.includes("storefront_checkout_rate_limits"),"Checkout migration must include idempotency and server-side attempt limiting");
assert.ok(idempotencyMigration.includes("REVOKE ALL ON FUNCTION builder.place_storefront_order("),"Legacy direct order RPC must be private so checkout cannot bypass idempotency and rate limits");
assert.ok(!bundle["admin/neon-auth.js"].includes("AUTHORIZED_EMAIL")&&!bundle["admin/neon-client.js"].includes("OWNER_EMAIL"),"Production auth bundle must support independent merchant accounts");
assert.ok(bundle["admin/neon-auth.js"].includes("signUp.email"),"Workspace must provide merchant account creation");
assert.ok(!bundle["admin/neon-preview-auth.js"].includes("halalfoodbd.official@gmail.com"),"Private preview must accept any authenticated merchant owner");
assert.ok(bundle["admin/wordpress-templates.js"].includes("updateBrowserPreviewLinks")&&!bundle["admin/wordpress-templates.js"].includes('encodeURIComponent("hf-"+t.key)'),"Template preview must resolve the signed-in merchant's own store slug");
assert.ok(storefront.includes("window.WPNeonClientReady"),"Private preview must reuse the independent WordPress Neon session");
assert.ok(tenantMigration.includes("ALTER POLICY owner_identity_guard"),"Legacy single-owner restrictive policies must be neutralized only after replacement tenant guards exist");
assert.doesNotThrow(()=>new Function(api),"Shared storefront API must parse");
assert.doesNotThrow(()=>new Function(adminApi),"Admin API must parse");
assert.doesNotThrow(()=>new Function(storefront),"Shared storefront runtime must parse");
assert.doesNotThrow(()=>new Function(bundle["admin/neon-auth.js"]),"Merchant auth and signup runtime must parse");
assert.doesNotThrow(()=>new Function(bundle["admin/neon-client.js"]),"Merchant Neon client runtime must parse");
console.log("Grocery commerce integration and preview regression checks passed.");
